Lemma rw_cells_C8_zero_split : forall m A cs, rw_cells bsegs m A (C8 (Z_to_bv 64 0) :: cs) -> rw_cells bsegs m A (C4 (Z_to_bv 64 0) :: C4 (Z_to_bv 64 0) :: cs).
